  "candidate_specs": [
    {
      "candidate_id": "cand_001",
      "high_level_variant": "Maintain same map and mission but bring the slower linear actor closer into the ego’s lane at low relative speed to ensure a short-distance interaction and likely contact while planning still produces non-blocked final waypoints.",
      "mutation_intent": "Tighten proximity between ego and a single slow-moving actor directly ahead/alongside, increasing the chance of contact while preserving the pattern: another actor within a few meters, active perception/prediction, available non-blocked final waypoints, and ambiguous ego actuation versus motion history.",
      "expected_oracle": "collision",
      "modifications": {
        "weather_delta": {
