              "x": -0.5,
              "y": 2.0
            },
            "speed_delta": 0.5
          }
        ],
        "puddle_mutations": [
          {
            "puddle_index": 0,
            "location_offset": {
              "x": 1.0,
              "y": -1.0
            },
            "level_delta": 0.0,
            "size_scale": 1.0
          },
          {
            "puddle_index": 1,
            "location_offset": {
              "x": -1.0,
              "y": 1.0
            },
            "level_delta": 0.0,
            "size_scale": 1.0
          }
        ],
        "mission_mutation": {
          "keep_original": true,
          "spawn_offset": {
            "x": 0.0,
            "y": 0.0
          },
          "destination_offset": {
            "x": 0.0,
            "y": 0.0
          }
        }
      },
      "pre_execution_validation_rules": [
        "Ensure at least one non-ego actor (e.g., index 0 or 1) is spawned within 5 m Euclidean distance of the ego trajectory within the last 5 s before the planned end of the run.",
        "Verify that perception detection topics (e.g., /detection/objects) contain at least one object in the 5 s window preceding any potential collision time.",
        "Verify that prediction topics (e.g., /prediction/objects) are published and contain at least one predicted object in the same window.",
        "Confirm that planning final waypoints are non-empty and structurally valid (e.g., ~O(100) points) throughout the scenario with no global failure before the anticipated collision window."
      ],
      "post_execution_validation_rules": [
        "Check the oracle or simulator logs for a collision event involving the ego and a non-ego actor (index 0 or 1), not just a near-miss.",
        "Compute the minimum distance between ego and each non-ego actor in the 5 s window before collision; require at least one to be within 3 m shortly before impact.",
        "Confirm that final waypoints remain available and non-null (similar count as earlier in the run) up to within 1 s of the collision time, with no global ‘blocked’ or emergency-stop flags dominating the final rows.",
        "Verify that perception and prediction topics contain at least one object in the 3 s before collision; do not require that the specific colliding actor be conclusively matched.",
        "Inspect vehicle command and vehicle status traces: allow inconsistency (e.g., zero throttle commands while ego speed is nonzero) and do not reject the case solely for such discrepancies, to preserve attribution uncertainty."
      ],
      "uncertainty": [
        "The exact mechanism of contact (which actor moves into whom, and whether the ego is nominally stopped) is left unconstrained to maintain ambiguity.",
        "No explicit guarantee is imposed that the colliding actor is the same as any perceived object, only that at least one object exists in detection/prediction streams.",
        "Actuation and vehicle-status consistency is intentionally not enforced, so root-cause localization can remain uncertain between planning, control, and simulation artifacts."
      ]
    },
    {
      "candidate_id": "cand_002",
      "high_level_variant": "Shift the linear actor laterally to create a low-speed side-swipe or merging-style interaction near the ego, with slightly adjusted mission endpoints to keep interaction in a similar region while still preserving ambiguous actuation evidence and non-blocked waypoints.",
      "mutation_intent": "Create a lateral-encounter geometry (side approach or near-parallel path) that still ensures a nearby actor within a few meters and eventual collision, stressing prediction and lane-keeping while leaving actuation/vehicle-status consistency unconstrained.",
      "expected_oracle": "collision",
      "modifications": {
        "weather_delta": {
          "rain": 2,
          "fog": 3,
          "wetness": 5,
          "puddle": 0
        },
        "actor_mutations": [
          {
            "actor_index": 0,
            "position_offset": {
              "x": -1.0,
              "y": -2.0
            },
            "speed_delta": -0.5
          },
          {
            "actor_index": 1,
            "position_offset": {
              "x": 1.5,
              "y": -3.0
            },
            "speed_delta": 1.0
          }
        ],
        "puddle_mutations": [
          {
            "puddle_index": 0,
            "location_offset": {
              "x": -2.0,
              "y": 0.0
            },
            "level_delta": 0.05,
            "size_scale": 1.1
          },
          {
            "puddle_index": 1,
            "location_offset": {
              "x": 2.0,
              "y": 0.0
            },
            "level_delta": -0.05,
            "size_scale": 0.9
          }
        ],
        "mission_mutation": {
          "keep_original": false,
          "spawn_offset": {
            "x": 2.0,
            "y": -3.0
          },
          "destination_offset": {
            "x": -3.0,
            "y": 2.0
          }
        }
      },
      "pre_execution_validation_rules": [
        "Check that the adjusted ego mission still traverses the region where actors 0 and 1 operate so that at least one actor can be within 5 m of the ego path during the run.",
        "Ensure that at least one non-ego actor reaches a pose within 4 m of the ego in the time interval 20–35 s of simulation time (or equivalent mid-run window).",
        "Verify that planning final waypoints, lane waypoints, and related topics remain valid (non-empty) through the mid-run window and do not indicate a permanent planning failure.",
        "Confirm that perception detection and prediction topics each contain at least one object instance in the few seconds leading up to the expected interaction window."
      ],
      "post_execution_validation_rules": [
        "Verify that the oracle reports a collision involving ego and a non-ego actor (0 or 1), potentially a lateral side-swipe or merge, rather than only a rear-end style event.",
        "Confirm that at least one actor is within 3 m of the ego within 2 s before the collision timestamp based on ground-truth /carla/objects or equivalent.",
        "Check that final waypoints remain present and non-null for the last planning cycle executed before collision, with no evidence that the planner intentionally cleared or blocked all waypoints well before the event.",
        "Confirm that detection and prediction topics contain at least one object in the last 3 s before collision without requiring that the colliding actor be uniquely identified.",
        "Allow and record any inconsistency between vehicle command topics (throttle, brake, steer) and vehicle status (velocity, acceleration), but do not filter out the case on this basis so that failure attribution remains uncertain."
      ],
      "uncertainty": [
        "The exact lateral configuration and which actor side-swipes the other is not fixed, only that collision occurs with a nearby actor under active planning and perception.",
        "Slightly increased rain/fog/wetness are not required to be causal; they may or may not affect perception quality and are treated as secondary factors.",
        "The link between prediction outputs and the eventual colliding trajectory is not enforced, preserving ambiguity over whether the system properly predicted the colliding actor."
      ]
    }
  ]
}

